package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="inventory_physical_count_attempt") public class IntentoConteoFisico{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="inventory_physical_count_line_id",nullable=false,updatable=false)private UUID lineaId;@Column(name="attempt_number",nullable=false,updatable=false)private int intento;@Column(name="counted_quantity",nullable=false,updatable=false)private BigDecimal cantidad;@Column(name="counted_at",insertable=false,updatable=false)private OffsetDateTime contadoEn;@Column(name="counted_by",nullable=false,updatable=false)private UUID contadoPor;protected IntentoConteoFisico(){}public IntentoConteoFisico(UUID l,int i,BigDecimal c,UUID u){lineaId=l;intento=i;cantidad=c;contadoPor=u;}}
